using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using MAEK.Tests;
namespace MAEK.Editor {
 public static class BuildPipeServices {
  const string Root="Assets/MAEK";
  [Serializable] class Report {public string status;public int pipes,services;public List<PhysicsCheck> checks;}
  [MenuItem("MAEK/Build pipe service environment")]
  public static void Run(){try{Build();if(Application.isBatchMode)EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);if(Application.isBatchMode)EditorApplication.Exit(1);else throw;}}
  static Material Mat(string key,float[] rgb){string path=Root+"/Generated/Materials/SERVICE_"+key+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,path);}m.color=new Color(rgb[0],rgb[1],rgb[2]);m.SetFloat("_Metallic",.45f);m.SetFloat("_Glossiness",.35f);return m;}
  static GameObject Part(PrimitiveType type,string name,Transform parent,Vector3 p,Vector3 scale,Material mat){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(parent,false);g.transform.position=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;g.layer=8;return g;}
  static void Info(GameObject g,string id){var info=g.AddComponent<MAEKAssetInfo>();info.assetId=id;info.sourceObjects=new[]{id};info.colliderPolicy="static primitive collider; virtual utility demonstration";}
  static void Annotate(GameObject g,ServicePipe p,PipeServiceDefinition d){var info=g.GetComponent<MAEKPipeService>()??g.AddComponent<MAEKPipeService>();info.lineId=p.id;info.serviceCode=p.serviceCode;info.medium=p.medium;info.purpose=d.purpose;info.fromNode=p.fromNode;info.toNode=p.toNode;info.normalState=p.state;info.flowBasis=p.flowBasis;}
  static bool RouteClear(DroneRoute route){int mask=1<<8;for(int k=0;k<route.waypoints.Length;k++){var p=MAEKDroneInspection.V(route.waypoints[k].position);if(Physics.CheckSphere(p,route.radius,mask,QueryTriggerInteraction.Ignore))return false;if(k>0){var a=MAEKDroneInspection.V(route.waypoints[k-1].position);var d=p-a;if(d.magnitude>1e-6&&Physics.SphereCast(a,route.radius,d.normalized,out var hit,d.magnitude,mask,QueryTriggerInteraction.Ignore))return false;}}return true;}
  static void Render(Camera camera,string path){var rt=new RenderTexture(1400,900,24);camera.targetTexture=rt;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1400,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1400,900),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}
  public static void Build(){
   var scene=EditorSceneManager.OpenScene(Root+"/Scenes/MAEKFurnaceCFD.unity");string output=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../visualization/pipe_services"));Directory.CreateDirectory(output);
   var json=AssetDatabase.LoadAssetAtPath<TextAsset>(Root+"/Source/pipe_services.json");var data=JsonUtility.FromJson<PipeServiceData>(json.text);var definitions=data.services.ToDictionary(d=>d.code);var existing=UnityEngine.Object.FindObjectsByType<MAEKAssetInfo>(FindObjectsSortMode.None).ToDictionary(a=>a.assetId);
   var checks=new List<PhysicsCheck>();Action<string,bool,string> check=(n,p,d)=>checks.Add(new PhysicsCheck{name=n,pass=p,detail=d});
   foreach(var p in data.pipes.Where(p=>!p.newGeometry)){if(!existing.ContainsKey(p.id))throw new Exception("Missing original pipe "+p.id);Annotate(existing[p.id].gameObject,p,definitions[p.serviceCode]);}
   var skid=new GameObject("Independent nitrogen and instrument-air demonstration");Info(skid,"UTIL.SKID");
   foreach(var a in data.utilityAssets){var d=MAEKPipeServices.V(a.size);var g=Part(a.shape=="cylinder"?PrimitiveType.Cylinder:PrimitiveType.Cube,a.id,skid.transform,MAEKPipeServices.V(a.position),a.shape=="cylinder"?new Vector3(d.x,d.y*.5f,d.z):d,Mat(a.id.Replace('.','_'),a.color));Info(g,a.id);if(a.shape=="cylinder"){UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());var mc=g.AddComponent<MeshCollider>();mc.sharedMesh=g.GetComponent<MeshFilter>().sharedMesh;}}
   foreach(var p in data.pipes.Where(p=>p.newGeometry)){var g=new GameObject(p.id);g.transform.SetParent(skid.transform,false);Info(g,p.id);Annotate(g,p,definitions[p.serviceCode]);var material=Mat(p.serviceCode,new[]{.36f,.39f,.41f});for(int k=1;k<p.points.Length;k++){var a=MAEKPipeServices.V(p.points[k-1].position);var b=MAEKPipeServices.V(p.points[k].position);var rod=Part(PrimitiveType.Cylinder,p.id+" segment "+k,g.transform,(a+b)*.5f,new Vector3(p.radius*2,(b-a).magnitude*.5f,p.radius*2),material);rod.transform.rotation=Quaternion.FromToRotation(Vector3.up,b-a);if(k<p.points.Length-1)Part(PrimitiveType.Sphere,p.id+" elbow "+k,g.transform,b,Vector3.one*p.radius*2,material);}}
   Physics.SyncTransforms();
   // New utilities may touch their own declared ports; all other penetrations fail.
   foreach(var p in data.pipes.Where(p=>p.newGeometry)){var collisions=new HashSet<string>();for(int k=1;k<p.points.Length;k++){var a=MAEKPipeServices.V(p.points[k-1].position);var b=MAEKPipeServices.V(p.points[k].position);var d=b-a;foreach(var h in Physics.SphereCastAll(a,p.radius*.98f,d.normalized,d.magnitude,1<<8,QueryTriggerInteraction.Ignore)){var i=h.collider.GetComponentInParent<MAEKAssetInfo>();if(i&&i.assetId!=p.id&&i.assetId!=p.fromEquipment&&i.assetId!=p.toEquipment)collisions.Add(i.assetId);}}check("utility pipe clearance "+p.id,collisions.Count==0,string.Join(",",collisions));}
   var originalRoutes=JsonUtility.FromJson<DroneRouteSet>(File.ReadAllText(Root+"/Source/drone_routes.json"));var routes=originalRoutes.routes.ToList();foreach(var p in data.pipes.Where(p=>p.newGeometry)){var waypoints=p.points.Select(point=>{var target=MAEKPipeServices.V(point.position);var camera=target+new Vector3(0,3,-2);return new DroneWaypoint{position=new[]{camera.x,camera.y,camera.z},target=new[]{target.x,target.y,target.z}};}).ToArray();routes.Add(new DroneRoute{id=p.id,from=p.fromNode,to=p.toNode,radius=.12f,samples=waypoints.Length,waypoints=waypoints});}
   foreach(var route in routes)check("drone "+route.id,RouteClear(route),"0.12m swept-sphere route against old and new colliders");
   string routePath=Root+"/Source/service_drone_routes.json";File.WriteAllText(routePath,JsonUtility.ToJson(new DroneRouteSet{routes=routes.ToArray()},true));AssetDatabase.ImportAsset(routePath,ImportAssetOptions.ForceSynchronousImport);var drone=UnityEngine.Object.FindFirstObjectByType<MAEKDroneInspection>();drone.routeData=AssetDatabase.LoadAssetAtPath<TextAsset>(routePath);
   var controller=new GameObject("MAEK pipe services and inspection context").AddComponent<MAEKPipeServices>();controller.definitions=json;controller.Initialize();check("all pipes have purpose",controller.BoundPipeCount==247&&data.services.Length==14,"240 original + 7 utility pipes, 14 service categories");controller.SetFilter("N2");check("filter selects matching pipe",controller.SelectedId=="UTIL-N001","Nitrogen filter selects a nitrogen pipe immediately");controller.SetFilter("");check("panel pointer does not lock walking camera",controller.PointerOverPanel(new Vector2(Screen.width-40,Screen.height*.5f))&&!controller.PointerOverPanel(new Vector2(1,1)),"Walking input respects the service panel rectangle");
   var cfd=UnityEngine.Object.FindFirstObjectByType<MAEKCFDPlayback>();cfd.startInCFDView=false;cfd.Initialize();check("exterior remains whole before CFD view",!cfd.ActiveView&&existing["BF1.BF"].GetComponent<Renderer>().sharedMaterials.All(m=>m.GetFloat("_Section")==0),"Start in pipe inspection; P can enter preserved CFD view");cfd.SetView(true);cfd.SetView(false);check("CFD and walking still switch",UnityEngine.Object.FindFirstObjectByType<MAEKWalkthrough>().enabled&&drone.enabled,"View ownership restored");cfd.DisposePreview();
   controller.SelectPipe("UTIL-N003");controller.FocusSelected();check("service selection focuses matching route",drone.InspectionActive&&drone.CurrentLineId=="UTIL-N003","Inspection camera pauses on selected pipe");controller.SetFilter("INSTR_AIR");controller.SynchronizeInspectionSelection();check("browse another service while inspection is paused",controller.SelectedId=="UTIL-I001","Current drone route does not overwrite a new panel selection");controller.FocusSelected();check("refocus after service change",drone.CurrentLineId=="UTIL-I001","Instrument air selection changes camera route");drone.EndInspection();controller.SetFilter("");
   check("old mesh colliders preserved",existing.Values.Sum(a=>a.GetComponents<MeshCollider>().Length)==323,"Original colliders retained; utility colliders added");
   var camera=new GameObject("Service preview camera").AddComponent<Camera>();camera.enabled=false;camera.fieldOfView=50;camera.nearClipPlane=.03f;camera.farClipPlane=1500;
   var origin=MAEKPipeServices.V(data.utilityOrigin);camera.transform.position=origin+new Vector3(4,5.5f,-8);camera.transform.LookAt(origin+new Vector3(3.2f,1.3f,-.8f));Render(camera,Path.Combine(output,"utility_services.png"));
   camera.transform.position=new Vector3(-125,85,110);camera.transform.LookAt(new Vector3(-60,20,15));Render(camera,Path.Combine(output,"pipe_service_overview.png"));UnityEngine.Object.DestroyImmediate(camera.gameObject);controller.RestoreColors();
   var report=new Report{status=checks.All(c=>c.pass)?"PASS":"FAIL",pipes=data.pipes.Length,services=data.services.Length,checks=checks};File.WriteAllText(Path.Combine(output,"unity_service_report.json"),JsonUtility.ToJson(report,true));if(report.status!="PASS")throw new Exception("Service validation: "+string.Join(";",checks.Where(c=>!c.pass).Select(c=>c.name+" "+c.detail)));
   EditorSceneManager.SaveScene(scene,Root+"/Scenes/MAEKPipeServices.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Root+"/Scenes/MAEKPipeServices.unity",true)};AssetDatabase.SaveAssets();AssetDatabase.ExportPackage(Root,Path.Combine(output,"MAEK_Pipe_Services.unitypackage"),ExportPackageOptions.Recurse);Debug.Log("PIPE_SERVICES_COMPLETE checks="+checks.Count);
  }
 }
}
